<?php
$ph=implode(',',array_fill(0,count($coordProgrammeTypes),'?'));
$params=array_merge($coordProgrammeTypes,[$currentSemesterId]);
$students=$coordProgrammeTypes?safeRun($pdo,"SELECT s.*,u.full_name,su.full_name supervisor_name,ru.full_name report_panel_name,pu.full_name presentation_panel_name
 FROM students s JOIN users u ON u.id=s.user_id
 LEFT JOIN lecturers sl ON sl.id=s.supervisor_id LEFT JOIN users su ON su.id=sl.user_id
 LEFT JOIN lecturers rl ON rl.id=s.report_panel_id LEFT JOIN users ru ON ru.id=rl.user_id
 LEFT JOIN lecturers pl ON pl.id=s.presentation_panel_id LEFT JOIN users pu ON pu.id=pl.user_id
 WHERE s.programme_type IN ($ph) AND s.semester_id=? ORDER BY u.full_name",$params)->fetchAll():[];
$workloads=[];
if($coordProgrammeTypes){
 $workloads=safeRun($pdo,"SELECT l.id,u.full_name,GROUP_CONCAT(DISTINCT lr.role_type ORDER BY lr.role_type) eligible_roles,
  (SELECT COUNT(*) FROM students sr WHERE sr.report_panel_id=l.id AND sr.semester_id=? AND sr.programme_type IN ($ph)) report_count,
  (SELECT COUNT(*) FROM students sp WHERE sp.presentation_panel_id=l.id AND sp.semester_id=? AND sp.programme_type IN ($ph)) presentation_count
  FROM lecturers l JOIN users u ON u.id=l.user_id JOIN lecturer_roles lr ON lr.lecturer_id=l.id
  WHERE u.status='active' AND lr.semester_id=? AND lr.programme_type IN ($ph) AND lr.role_type IN ('report_panel','presentation_panel')
  GROUP BY l.id,u.full_name ORDER BY u.full_name",array_merge([$currentSemesterId],$coordProgrammeTypes,[$currentSemesterId],$coordProgrammeTypes,[$currentSemesterId],$coordProgrammeTypes))->fetchAll();
}
$panelOptions=[];
foreach($students as $student){
 $studentId=(int)$student['id'];$supervisorId=(int)($student['supervisor_id']??0);
 $panelOptions[$studentId]['report']=safeRun($pdo,"SELECT DISTINCT l.id,u.full_name,(SELECT COUNT(*) FROM students x WHERE x.report_panel_id=l.id AND x.semester_id=?) assignment_count FROM lecturer_roles lr JOIN lecturers l ON l.id=lr.lecturer_id JOIN users u ON u.id=l.user_id WHERE lr.role_type='report_panel' AND lr.programme_type=? AND lr.semester_id=? AND u.status='active' AND l.id<>? ORDER BY u.full_name",[$currentSemesterId,$student['programme_type'],$currentSemesterId,$supervisorId])->fetchAll();
 $panelOptions[$studentId]['presentation']=safeRun($pdo,"SELECT DISTINCT l.id,u.full_name,(SELECT COUNT(*) FROM students x WHERE x.presentation_panel_id=l.id AND x.semester_id=?) assignment_count FROM lecturer_roles lr JOIN lecturers l ON l.id=lr.lecturer_id JOIN users u ON u.id=l.user_id WHERE lr.role_type='presentation_panel' AND lr.programme_type=? AND lr.semester_id=? AND u.status='active' AND l.id<>? ORDER BY u.full_name",[$currentSemesterId,$student['programme_type'],$currentSemesterId,$supervisorId])->fetchAll();
}
?>
<?php if(($_GET['saved']??'')==='1'): ?><div class="alert alert-success small">Panel assignments and the shared panel date were saved.</div><?php endif; ?>
<?php if(($_GET['completed']??'')==='1'): ?><div class="alert alert-success small">Panel session status updated. Report Panel and Presentation Panel evaluations are now unlocked when the session was marked completed.</div><?php endif; ?>
<?php if(($_GET['error']??'')==='invalid'): ?><div class="alert alert-danger small">The assignment was not saved. Select a valid date and two different active panel lecturers for the correct programme; neither can be the supervisor.</div><?php endif; ?>
<div class="card-fy mb-3"><div class="section-title">Panel Lecturer Workload</div><p class="small text-muted">Current-semester assignments across the programmes you coordinate.</p><div class="table-responsive"><table class="table-fy"><thead><tr><th>Lecturer</th><th>Eligible Panel Roles</th><th>Report Panel Students</th><th>Presentation Panel Students</th></tr></thead><tbody><?php foreach($workloads as $w): ?><tr><td><strong><?= e(drName($w['full_name'])) ?></strong></td><td><?php foreach(explode(',',$w['eligible_roles']) as $role): ?><span class="badge-fy badge-info me-1"><?= e(roleLabel($role)) ?></span><?php endforeach; ?></td><td><?= (int)$w['report_count'] ?></td><td><?= (int)$w['presentation_count'] ?></td></tr><?php endforeach; ?><?php if(!$workloads): ?><tr><td colspan="4" class="text-center text-muted py-4">No eligible panel lecturers found.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card-fy"><div class="section-title">Assign Report and Presentation Panels</div><p class="small text-muted">Both panels use the same panel date. They can submit evaluations only after you mark the panel session completed.</p><div class="table-responsive"><table class="table-fy"><thead><tr><th>Student</th><th>Project Title</th><th>Supervisor</th><th>Report Panel</th><th>Presentation Panel</th><th>Panel Date</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($students as $student): $isScheduled=$student['presentation_status']==='scheduled';$canComplete=$isScheduled&&!empty($student['presentation_date'])&&date('Y-m-d',strtotime($student['presentation_date']))<=date('Y-m-d'); ?>
<tr><td><strong><?= e($student['full_name']) ?></strong><div class="small text-muted"><?= e($student['matric_number']) ?> · <?= e(programmeTypeLabel($student['programme_type'])) ?></div></td><td class="small"><?= e($student['project_title']?:'No project title') ?></td><td><?= e($student['supervisor_name']?drName($student['supervisor_name']):'Not assigned') ?></td><td><?= e($student['report_panel_name']?drName($student['report_panel_name']):'Not assigned') ?></td><td><?= e($student['presentation_panel_name']?drName($student['presentation_panel_name']):'Not assigned') ?></td><td><?= $student['presentation_date']?e(date('M j, Y',strtotime($student['presentation_date']))):'Not set' ?></td><td><span class="badge-fy badge-<?= $student['presentation_status']==='completed'?'success':($isScheduled?'warning':'secondary') ?>"><?= e(ucwords(str_replace('_',' ',$student['presentation_status']))) ?></span></td><td><div class="d-flex flex-column gap-2"><button type="button" class="btn-fy-outline btn-sm" data-bs-toggle="modal" data-bs-target="#panels<?= (int)$student['id'] ?>">Assign / Schedule</button><?php if($canComplete): ?><form method="post" onsubmit="return confirm('Mark the shared Report and Presentation Panel session as completed? This unlocks both panel evaluations.')"><?= csrfField() ?><input type="hidden" name="action" value="complete_presentation"><input type="hidden" name="student_id" value="<?= (int)$student['id'] ?>"><button class="btn-fy-orange btn-sm w-100">Mark Completed</button></form><?php elseif($isScheduled): ?><span class="small text-muted">Can be completed on or after the panel date.</span><?php endif; ?></div></td></tr>
<?php endforeach; ?><?php if(!$students): ?><tr><td colspan="8" class="text-center text-muted py-4">No students are enrolled in your coordinated programmes for the current semester.</td></tr><?php endif; ?>
</tbody></table></div></div>
<?php foreach($students as $student): $reportPanels=$panelOptions[(int)$student['id']]['report']??[];$presentationPanels=$panelOptions[(int)$student['id']]['presentation']??[]; ?>
<div class="modal fade" id="panels<?= (int)$student['id'] ?>" tabindex="-1" aria-hidden="true"><div class="modal-dialog"><div class="modal-content" style="border-radius:18px"><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="assign_panels"><input type="hidden" name="student_id" value="<?= (int)$student['id'] ?>"><div class="modal-header"><h6 class="modal-title">Panels — <?= e($student['full_name']) ?></h6><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">
<label class="form-label small fw-semibold">Report Panel</label><select required name="report_panel_id" class="form-control-fy w-100 mb-3 panel-select" data-student="<?= (int)$student['id'] ?>" data-kind="report"><option value="">Select report panel</option><?php foreach($reportPanels as $lecturer): ?><option value="<?= (int)$lecturer['id'] ?>" <?= (int)$student['report_panel_id']===(int)$lecturer['id']?'selected':'' ?>><?= e(drName($lecturer['full_name'])) ?> — <?= (int)$lecturer['assignment_count'] ?> current student(s)</option><?php endforeach; ?></select>
<label class="form-label small fw-semibold">Presentation Panel</label><select required name="presentation_panel_id" class="form-control-fy w-100 mb-3 panel-select" data-student="<?= (int)$student['id'] ?>" data-kind="presentation"><option value="">Select presentation panel</option><?php foreach($presentationPanels as $lecturer): ?><option value="<?= (int)$lecturer['id'] ?>" <?= (int)$student['presentation_panel_id']===(int)$lecturer['id']?'selected':'' ?>><?= e(drName($lecturer['full_name'])) ?> — <?= (int)$lecturer['assignment_count'] ?> current student(s)</option><?php endforeach; ?></select>
<label class="form-label small fw-semibold">Panel Date</label><input required type="date" name="panel_date" class="form-control-fy w-100 mb-3" value="<?= $student['presentation_date']?e(date('Y-m-d',strtotime($student['presentation_date']))):'' ?>">
<label class="form-label small fw-semibold">Venue / Room (optional)</label><input name="presentation_venue" class="form-control-fy w-100" maxlength="150" value="<?= e($student['presentation_venue']??'') ?>"><div class="small text-muted mt-2">The same date applies to both panels. The panel lecturers must be different, and neither may be the supervisor.</div></div><div class="modal-footer"><button class="btn-fy-orange w-100">Save Assignments and Date</button></div></form></div></div></div>
<?php endforeach; ?>
<script>document.querySelectorAll('.panel-select').forEach(function(select){select.addEventListener('change',function(){const id=this.dataset.student,report=document.querySelector('.panel-select[data-student="'+id+'"][data-kind="report"]'),presentation=document.querySelector('.panel-select[data-student="'+id+'"][data-kind="presentation"]');if(report&&presentation&&report.value&&report.value===presentation.value){alert('Report Panel and Presentation Panel must be different lecturers.');this.value='';}});});</script>
